import data from "./data/gs1_dictionary.json";

/**
 * The GS1 Barcode Syntax Dictionary as the resolver's portal used it (`portal/gs1_dictionary.json`, generated by its
 * `tools/gen_dictionary.py` from the dictionary of Syntax Engine release 1.4.1 — the release of `gs1encoder` here; now
 * made from each release's sources by `scripts/syntax-engine.mjs`, which gives the resolver's file byte for byte):
 * each AI's title, flags, format components, requirements and exclusions, and for primary keys the qualifiers that go
 * in their GS1 Digital Link path. Ported from `portal/gs1dict.py` (ADR 0004).
 *
 * Flags: "?" — may be a GS1 Digital Link data attribute; "*" — the element string has a predefined length.
 */
export type ComponentType = "N" | "X" | "Y" | "Z";

export interface Component {
  type: ComponentType;
  min: number;
  max: number;
  optional: boolean;
  linters: string[];
}

export interface AiEntry {
  title: string;
  flags: string;
  components: Component[];
  req: string[][][];
  ex: string[][][];
  /** Primary keys only: the alternative ordered sequences of qualifiers ([[]] for a key without any). */
  dlpkey?: string[][];
}

export const DICTIONARY = data as unknown as { release: string; dictionary: string; ais: Record<string, AiEntry> };

/**
 * The GS1 Barcode Syntax Engine release that checks every input and makes the forms the symbols carry (`gs1encoder`;
 * gs1_dictionary.json is made from the same release's sources, and a test holds the two equal), and its dictionary's
 * release date. The screen and the files made name it, so that a symbol can be traced to the rules it was checked by.
 */
export const SYNTAX_ENGINE: { readonly release: string; readonly dictionary: string } = {
  release: DICTIONARY.release,
  dictionary: DICTIONARY.dictionary,
};

/** The engine as the files made name it, in English: "GS1 Barcode Syntax Engine 1.4.1". */
export const SYNTAX_ENGINE_NAME = `GS1 Barcode Syntax Engine ${SYNTAX_ENGINE.release}`;

export function aiEntry(ai: string): AiEntry | undefined {
  return DICTIONARY.ais[ai];
}

const DATE_LINTERS = new Set(["yymmd0", "yymmdd"]);
const FULL_YEAR_LINTERS = new Set(["yyyymmdd"]);

/** Whether an AI's first component carries one of the linters. */
const startsWith = (ai: string, linters: Set<string>) => aiEntry(ai)?.components[0]?.linters.some((l) => linters.has(l)) ?? false;

/**
 * Whether an AI's value starts with a date whose year has four digits, YYYYMMDD, such as (7250) DOB or (7251) DOB TIME
 * (backlog 4.2): a date of birth, whose century the General Specifications' rule for YYMMDD could not choose.
 */
export function isFullYearDate(ai: string): boolean {
  return startsWith(ai, FULL_YEAR_LINTERS);
}

/**
 * Whether an AI's value starts with a date, YYMMDD as (17) or (7003), or YYYYMMDD as (7250) (`isFullYearDate`): a
 * bulk cell read as a date, a date field's format.
 */
export function isDateAi(ai: string): boolean {
  return startsWith(ai, DATE_LINTERS) || isFullYearDate(ai);
}

const TIME_LINTERS = new Set(["hhmi", "hh", "mi", "ss"]);

/**
 * Whether a date AI's value goes on, after its date, with a time: hours, then minutes, then seconds, some of them
 * optional, such as (7003) YYMMDDHHMM, (7011) YYMMDD[HHMM], (8008) YYMMDDHH[MM[SS]] or (7251) YYYYMMDDHHMM; a date
 * field's hh, mm and ss.
 */
export function carriesTime(ai: string): boolean {
  return isDateAi(ai) && (aiEntry(ai)?.components.some((c) => c.linters.some((l) => TIME_LINTERS.has(l))) ?? false);
}

/**
 * Whether an AI's value is percent-encoded (the pcenc linter): a character outside the General Specifications' CSET 82,
 * such as a letter with an accent written as %XX for each of its UTF-8 bytes, a space as a plus sign, as the names and addresses of
 * (4300)–(4320) and (7253)–(7259).
 */
export function isPercentEncoded(ai: string): boolean {
  return startsWith(ai, PCENC_LINTERS);
}

const PCENC_LINTERS = new Set(["pcenc"]);

/** CSET 82 but the percent sign: what a percent-encoded value carries as it is. */
const CSET82_BUT_PERCENT = /[!"&'()*+,\-./0-9:;<=>?A-Z_a-z]/;

/**
 * Text as a percent-encoded AI takes it (`isPercentEncoded`): a space as a plus sign, as the General Specifications
 * say it should be (3.8.29, 7.11: "A space character should be encoded as a single plus symbol, +"), and each other
 * character outside CSET 82 as %XX for each of its UTF-8 bytes, in capitals (`Maria José` → `Maria+Jos%C3%A9`). A plus
 * sign already stands for a space and is kept, as is a percent sign followed by two hexadecimal digits, taken as
 * already encoded, so text encoded once is not encoded again (a plus sign meant as itself is typed %2B); any other
 * percent sign becomes %25.
 */
export function percentEncode(text: string): string {
  let out = "";
  for (let i = 0; i < text.length; ) {
    const char = String.fromCodePoint(text.codePointAt(i)!);
    if (char === " ") out += "+";
    else if (CSET82_BUT_PERCENT.test(char) || (char === "%" && /^[0-9A-Fa-f]{2}$/.test(text.slice(i + 1, i + 3)))) out += char;
    else for (const byte of new TextEncoder().encode(char)) out += `%${byte.toString(16).toUpperCase().padStart(2, "0")}`;
    i += char.length;
  }
  return out;
}

/**
 * A percent-encoded value as people read it (`Maria+Jos%C3%A9` and `Maria%20Jos%C3%A9` → `Maria José`): a plus sign
 * as a space, each run of %XX as the characters its UTF-8 bytes make (%2B a plus sign); a run that is not UTF-8 is kept
 * as it is.
 */
export function percentDecode(value: string): string {
  return value.replace(/\+|(?:%[0-9A-Fa-f]{2})+/g, (run) => {
    if (run === "+") return " ";
    try {
      return decodeURIComponent(run);
    } catch {
      return run;
    }
  });
}

/** Whether an AI's value is ISO/IEC 5218's code of a person's sex (the iso5218 linter), as (7252) BIO SEX. */
export function isSexCode(ai: string): boolean {
  return startsWith(ai, ISO5218_LINTERS);
}

const ISO5218_LINTERS = new Set(["iso5218"]);

// ISO/IEC 5218's codes from words people write, in English, Portuguese, Spanish, French, German and Italian, without
// their accents (data, not the interface's language: ADR 0003). Whole words only: a letter is not guessed, as M is
// male in English and Portuguese but female ('mujer') in Spanish, where H ('hombre') is male. Each list starts with a
// single word, as the web's catalogue test would take a first text with a space for a message to translate.
const SEX_WORDS: Record<string, string[]> = {
  "0": ["unknown", "not known", "desconhecido", "ignorado", "nao informado", "desconocido", "no informado", "inconnu",
    "non renseigne", "unbekannt", "keine angabe", "sconosciuto", "non noto"],
  "1": ["male", "man", "masculine", "masc", "masculino", "homem", "hombre", "varon", "masculin", "homme", "mannlich",
    "mann", "maschile", "maschio", "uomo"],
  "2": ["female", "woman", "feminine", "fem", "feminino", "mulher", "femenino", "mujer", "feminin", "femme", "weiblich",
    "frau", "femminile", "femmina", "donna"],
  "9": ["entfallt", "not applicable", "nao aplicavel", "nao se aplica", "no aplicable", "no aplica", "non applicable",
    "sans objet", "nicht zutreffend", "non applicabile"],
};

const SEX_BY_WORD = new Map(Object.entries(SEX_WORDS).flatMap(([code, words]) => words.map((w) => [w, code])));

/**
 * ISO/IEC 5218's code for a word that names a sex, in any of the six languages, whatever its case, accents or full stop
 * (`Masculino`, `männlich`, `masc.` → 1; `Feminino`, `FEMALE` → 2; `Desconhecido` → 0; `Não aplicável` → 9); anything
 * else, a digit or a letter such as F, is returned as it is, for the Syntax Engine to judge.
 */
export function sexCode(text: string): string {
  const words = text
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
  return SEX_BY_WORD.get(words) ?? text;
}

export interface Attribute {
  ai: string;
  title: string;
  components: Component[];
  /** Carried by element strings only: a GS1 Digital Link URI cannot (backlog 1.11). */
  elementStringOnly?: boolean;
}

/** The AIs permitted as GS1 Digital Link data attributes (flag "?"). */
export function dataAttributes(): Record<string, Attribute> {
  const out: Record<string, Attribute> = {};
  for (const [ai, entry] of Object.entries(DICTIONARY.ais)) {
    if (entry.flags.includes("?")) out[ai] = { ai, title: entry.title, components: entry.components };
  }
  return out;
}

/**
 * The AIs only element strings carry — neither a key, a qualifier nor a GS1 Digital Link attribute, such as (8014)
 * HIDRI, (8040) IMEI or (8200) PRODUCT URL —, marked `elementStringOnly` (backlog 1.11).
 */
export function elementStringAttributes(): Record<string, Attribute> {
  const out: Record<string, Attribute> = {};
  const withKeys = new Set(identifierKeys().flatMap((key) => [key, ...qualifiersOf(key)]));
  for (const [ai, entry] of Object.entries(DICTIONARY.ais)) {
    if (!entry.flags.includes("?") && !withKeys.has(ai)) {
      out[ai] = { ai, title: entry.title, components: entry.components, elementStringOnly: true };
    }
  }
  return out;
}

/**
 * GS1 identifiers a GS1 Digital Link URI cannot carry (GS1 General Specifications 26.0, section 1.3, whose tables say
 * "Not supported" for the Digital Link): the Made-to-Order GTIN (03), with its batch/lot (10) or serial number (21)
 * in element strings (1.3.1.6, 1.3.1.8). Backlog 1.11. The HIDRI (8014) needs a GTIN (01) beside it, so it is an
 * attribute of (01) rather than a key of its own.
 */
const ELEMENT_STRING_KEYS: Record<string, string[][]> = { "03": [["10", "21"]] };

/** A key's alternative ordered sequences of qualifiers: its GS1 Digital Link path's, or its element string's. */
function alternativesOf(key: string): string[][] {
  return aiEntry(key)?.dlpkey ?? ELEMENT_STRING_KEYS[key] ?? [];
}

/** For every key, the AIs that belong with it (its qualifiers): {"01": {"22", "10", "21", "235"}, "03": {"10", "21"}}. */
export function pathAis(): Record<string, Set<string>> {
  const out: Record<string, Set<string>> = {};
  for (const key of identifierKeys()) out[key] = new Set(alternativesOf(key).flat());
  return out;
}

/** The primary keys of a GS1 Digital Link URI, in the dictionary's order. */
export function primaryKeys(): string[] {
  return Object.entries(DICTIONARY.ais)
    .filter(([, entry]) => entry.dlpkey)
    .map(([ai]) => ai);
}

/** Every key the editor offers: the GS1 Digital Link primary keys, then those of element strings only ((03)). */
export function identifierKeys(): string[] {
  return [...primaryKeys(), ...Object.keys(ELEMENT_STRING_KEYS)];
}

/** Whether a GS1 Digital Link URI can carry the key; (03) only goes in element strings. */
export function isDigitalLinkKey(key: string): boolean {
  return Boolean(aiEntry(key)?.dlpkey);
}

/** The qualifiers of a key, in path order, each alternative sequence in turn (01: 22, 10, 21, then 235). */
export function qualifiersOf(key: string): string[] {
  return [...new Set(alternativesOf(key).flat())];
}

/** Whether two qualifiers of a key belong to different alternatives (01: 235 is not combined with 22, 10, 21). */
export function exclusiveQualifiers(key: string, a: string, b: string): boolean {
  return !alternativesOf(key).some((sequence) => sequence.includes(a) && sequence.includes(b));
}

/**
 * The qualifiers shown on the screen: the first `max` of the key's, and any other already chosen; the rest are behind
 * "+ Add qualifier" (the owner, 29 October 2026). No key of the General Specifications 26.0 has more than four.
 */
export function shownQualifiers(all: string[], chosen: string[], max = 4): { shown: string[]; more: string[] } {
  const shown = all.filter((ai, index) => index < max || chosen.includes(ai));
  return { shown, more: all.filter((ai) => !shown.includes(ai)) };
}

const SIZE: Record<ComponentType, [string, string]> = {
  N: ["{n} digits", "up to {n} digits"],
  X: ["{n} characters", "up to {n} characters"],
  Y: ["{n} characters (A–Z, 0–9, # - /)", "up to {n} characters (A–Z, 0–9, # - /)"],
  Z: ["{n} base64url characters", "up to {n} base64url characters"],
};

/** A value of one digit or character, as (7252) BIO SEX: "one digit", not "1 digits". */
const ONE: Partial<Record<ComponentType, string>> = { N: "one digit", X: "one character" };

const LINTS: Record<string, string> = {
  yymmd0: "date YYMMDD",
  yymmdd: "date YYMMDD",
  yyyymmdd: "date YYYYMMDD",
  hhmi: "time HHMM",
  hh: "hour HH",
  mi: "minutes MM",
  ss: "seconds SS",
  csum: "with check digit",
  csumalpha: "with check character pair",
  iso3166: "country, ISO 3166 numeric code (e.g. 826)",
  iso3166999: "country, ISO 3166 numeric code or 999",
  iso3166alpha2: "country, ISO 3166 two-letter code (e.g. GB)",
  iso4217: "currency, ISO 4217 numeric code (e.g. 826)",
  iso5218: "sex: 0 not known, 1 male, 2 female, 9 not applicable (ISO 5218), or the word",
  yesno: "0 = no, 1 = yes",
  hyphen: "“-” for a negative value",
  nonzero: "not zero",
  latitude: "latitude",
  longitude: "longitude",
  iban: "IBAN",
  key: "starts with a GS1 Company Prefix",
  pcenc: "spaces written as + and accents and other characters as %XX in the code (e.g. é as %C3%A9)",
  pieceoftotal: "piece and total, e.g. 0102 (piece 1 of 2)",
  posinseqslash: "position/total, e.g. 1/2",
  mediatype: "AIDC media type (2 digits)",
  winding: "0, 1 or 9 (winding direction)",
  zero: "always 0",
};

/** The format of an AI's value from its components, as the resolver wrote it: "6 digits · date YYMMDD". */
export function formatHint(components: Component[]): string {
  return components
    .map((c) => {
      const one = c.min === 1 && c.max === 1 && ONE[c.type];
      const size = one || SIZE[c.type][c.min === c.max ? 0 : 1]!.replace("{n}", String(c.max));
      const text = [size, ...c.linters.filter((l) => l in LINTS).map((l) => LINTS[l])].join(" · ");
      return c.optional ? `optional: ${text}` : text;
    })
    .join(" + ");
}
